'use strict';
const assert=require('node:assert/strict');
const fs=require('node:fs');
const path=require('node:path');
const root=path.resolve(__dirname,'../..');
const read=f=>fs.readFileSync(path.join(root,f),'utf8');
const mapper=read('docs/scifi-ui/scripts/formatx-apex-scene-stability.js');
const shape=read('docs/scifi-ui/scripts/formatx-core-shape-v14.js');
const material=read('docs/scifi-ui/scripts/formatx-core-mesh3d-material-v15.js');
const geometry=read('docs/scifi-ui/scripts/formatx-core-geometry-v13.js');
const mesh=read('docs/scifi-ui/scripts/formatx-core-mesh3d-v11.js');
const fracture=read('docs/scifi-ui/scripts/formatx-core-fracture3d-v11.js');
const kick=read('docs/scifi-ui/scripts/formatx-core-cinematic-kick-v11.js');
const grade=read('docs/scifi-ui/styles/formatx-core-cinematic-grade-v14.css');
const voice=read('docs/scifi-ui/scripts/organism-voice-stability.js');
const interaction=read('docs/scifi-ui/scripts/organism-core-interaction.js');
const infinite=read('docs/scifi-ui/scripts/formatx-infinite-scroll.js');
assert.match(mapper,/fxApexSceneStability==='ready-v25'/);
assert.match(mapper,/formatx-core-mesh3d-material-v15\.js\?v=20260809-object-space-center-v15/);
assert.match(mapper,/cinematic-reference-centered-glass-true-mesh3d-v25/);
assert.match(mapper,/reference-glass-v15-object-space-centered/);
assert.match(mapper,/true-3d-uniform-scale-1\.15-plus-y0\.72-vertex-shape/);
assert.doesNotMatch(mapper,/scrollTo\s*\(|scrollIntoView\s*\(|preventDefault\s*\(/);
assert.match(shape,/aPosition\.y\*\.72/);
assert.match(shape,/fxCoreShapeMesh='applied-v14'/);
assert.match(shape,/fxCoreShapeFracture='applied-v14'/);
assert.match(material,/vec2 cp=vec2\(vP\.x,vP\.y-\.18\)/,'material center must remove renderer Y offset');
assert.match(material,/float r=length\(cp\),a=atan\(cp\.y,cp\.x\)/);
assert.match(material,/float coreMask=1\.-sm\(\.030,\.082,r\)/);
assert.match(material,/float coreHalo=exp\(-r\*22\.0\)/);
assert.match(material,/float diag=pow\(abs\(sin\(a\*2\.0\)\),13\.0\)/);
assert.match(material,/float lineA=/);
assert.match(material,/float lineB=/);
assert.match(material,/float whiteFacet=/);
assert.match(material,/film\(c\*1\.82\)/);
assert.match(material,/fxCoreMeshMaterial='reference-glass-v15'/);
assert.match(material,/fxCoreMeshMaterialPatch='applied-v15'/);
assert.match(material,/fxCoreMaterialCenter='object-space-y-minus-0\.18'/);
assert.doesNotMatch(material,/drawImage\s*\(|new Image\s*\(|background-image/i);
assert.match(geometry,/value\*1\.15/);
assert.match(mesh,/getContext\('webgl2'/);
assert.match(mesh,/gl\.enable\(gl\.DEPTH_TEST\)/);
assert.match(mesh,/gl\.drawElements\(gl\.TRIANGLES/);
assert.match(fracture,/gl\.drawElements\(gl\.LINES/);
assert.match(grade,/brightness\(1\.16\)/);
assert.match(grade,/opacity: 0\.30/);
assert.match(kick,/formatx:organismresponse.*\.74,1\.15,2100/s);
assert.match(interaction,/formatx:organismcoreactivate/);
assert.match(voice,/window\.visualViewport/);
assert.match(voice,/keyboardInset/);
assert.match(infinite,/const VERSION = 'seamless-v7'/);
assert.match(infinite,/root\.dataset\.fxInfiniteInput = 'native'/);
console.log('PASS: v15 keeps true indexed WebGL2 reference-ratio geometry and fixes all radial glass/reactor effects into centered object space while preserving cinematic reactions and native scrolling.');
